def _get_user(self, username):
        """ get user attributes
        @str username: user to get
        @rtype: dict, {<attr>: <value>}
        """
        try:
            user = User.objects.get(username=username)
            return user.to_dict()
        except User.DoesNotExist:
            raise UserNotExist(username)

